@push('scripts')<script>
$(function(){
 const orderElement=document.getElementById('supportOrderModal');
 const orderModal=orderElement?new bootstrap.Modal(orderElement):null;
 const productModal=new bootstrap.Modal(document.getElementById('supportProductsModal'));
 const table=$('#supportOrdersTable').DataTable({processing:true,serverSide:true,responsive:true,ajax:{url:@json(route('super.support-material-orders.dt')),data:d=>{d.from_date=$('#supportFrom').val();d.to_date=$('#supportTo').val()}},columns:[{data:'DT_RowIndex',orderable:false,searchable:false},{data:'actions',orderable:false,searchable:false,className:'text-center'},{data:'number',name:'document.number'},{data:'order_date',name:'document.order_date',render:d=>d?new Date(d+'T00:00:00').toLocaleDateString():''},{data:'style',name:'style'},{data:'code',name:'product.code'},{data:'name',name:'product.name'},{data:'unit',orderable:false,searchable:false},{data:'quantity',name:'quantity'},{data:'po_other',name:'po_other'}],order:[[3,'desc']],drawCallback:()=>window.feather&&feather.replace()});
 const products=$('#supportProductsTable').DataTable({processing:true,serverSide:true,responsive:true,ajax:@json(route('super.support-material-orders.products.dt')),columns:[{data:'code',name:'code'},{data:'name',name:'name'},{data:'unit_label',orderable:false,searchable:false},{data:'actions',orderable:false,searchable:false}],drawCallback:()=>window.feather&&feather.replace()});
 function resetLine(){ $('#supportItemId,#supportProductId').val('');$('#supportProductLabel,#supportUnit,#supportQuantity,#supportPoOther,#supportStyle').val('');$('#cancelSupportEdit').addClass('d-none');$('#saveSupportOrder').html('<i data-feather="save" class="icon-sm me-1"></i>'+@json(__('ui.common.save')));window.feather&&feather.replace(); }
 function preview(){ $.get(@json(route('super.support-material-orders.number-preview'))).done(r=>$('#supportNumber').val(r.number)); }
 $('#newSupportOrder,#addSupportOrder').on('click',()=>{ $('#supportDocumentId').val('');$('#supportDate').val(@json(now()->toDateString()));resetLine();preview();orderModal.show(); });
 if(orderModal) preview(); $('#chooseSupportProduct').on('click',()=>{products.ajax.reload();orderModal.hide();productModal.show()});
 $(document).on('click','.btn-select-support-product',function(){let b=$(this);$('#supportProductId').val(b.data('id'));$('#supportProductLabel').val(b.data('code')+' — '+b.data('name'));$('#supportUnit').val(b.data('unit'));productModal.hide();orderModal.show()});
 $('#supportOrderForm').on('submit',function(e){e.preventDefault();let id=$('#supportItemId').val();$.ajax({url:id?@json(route('super.support-material-orders.update',['item'=>'__ID__'])).replace('__ID__',id):@json(route('super.support-material-orders.store')),method:id?'PUT':'POST',data:$(this).serialize()}).done(r=>{if(r.document_id){$('#supportDocumentId').val(r.document_id);$('#supportNumber').val(r.number)}table.ajax.reload(null,false);$('#supportNumber').val(r.number||$('#supportNumber').val());resetLine();if(id){orderModal.hide();$('#supportDocumentId').val('');preview()}Swal.fire({icon:'success',title:@json(__('ui.workflow.success')),text:r.message+' ('+(r.number||'')+')'});}).fail(x=>Swal.fire({icon:'error',title:@json(__('ui.workflow.failure')),text:Object.values(x.responseJSON?.errors||{}).flat().join('\n')||x.responseJSON?.message||'Error'}));});
 $(document).on('click','.btn-edit-support-order',function(){let b=$(this);$('#supportItemId').val(b.data('id'));$('#supportProductId').val(b.data('product'));$('#supportProductLabel').val(b.data('code')+' — '+b.data('name'));$('#supportUnit').val(b.data('unit'));$('#supportDate').val(b.data('date'));$('#supportQuantity').val(b.data('quantity'));$('#supportStyle').val(b.data('style'));$('#supportPoOther').val(b.data('po'));$('#supportDocumentId').val('');$('#supportNumber').val('');$('#cancelSupportEdit').removeClass('d-none');$('#saveSupportOrder').text(@json(__('ui.common.save_changes')));orderModal.show();});
 $('#cancelSupportEdit').on('click',()=>{resetLine();$('#supportDocumentId').val('');preview()}); $('#supportFilter').on('click',()=>table.ajax.reload());
 $('#supportExport').on('click',function(e){e.preventDefault();let q=new URLSearchParams();if($('#supportFrom').val())q.set('from_date',$('#supportFrom').val());if($('#supportTo').val())q.set('to_date',$('#supportTo').val());location.href=this.href+'?'+q.toString()});
 $(document).on('click','.btn-delete-support-order',function(){let id=$(this).data('id');Swal.fire({icon:'warning',title:@json(__('ui.common.confirm_delete')),showCancelButton:true,confirmButtonText:@json(__('ui.common.delete')),cancelButtonText:@json(__('ui.common.cancel'))}).then(x=>{if(x.isConfirmed)$.ajax({url:@json(route('super.support-material-orders.destroy',['item'=>'__ID__'])).replace('__ID__',id),method:'DELETE',data:{_token:@json(csrf_token())}}).done(r=>{table.ajax.reload(null,false);if(r.document_empty&&$('#supportDocumentId').val()){$('#supportDocumentId').val('');preview()}Swal.fire({icon:'success',text:r.message})}).fail(x=>Swal.fire({icon:'error',text:x.responseJSON?.message||'Error'}))})});
});
</script>@endpush
